function telegraph(e,kind,target=null){e.wind=e.boss?1.05:e.type===3?.72:.64;e.attackKind=kind;e.lock.copy(target||hero.position);const pos=kind==='slam'?e.lock:e.mesh.position;const r=kind==='slam'?2.5:e.boss?3.3:e.r+1.05;e.tele=groundRing(pos.x,pos.z,r,0xf5b378,.55);e.tele.userData.r=r;if(kind==='charge'){const p=e.mesh.position,d=e.lock.clone().sub(p).normalize();e.chargeDir=d;const marker=mesh(effects,'box',0xd7a478,p.x+d.x*2.5,.04,p.z+d.z*2.5,.7,.02,5);marker.rotation.y=Math.atan2(d.x,d.z);marker.material=mat(0xd7a478,.3,.27);e.line=marker}}
