let mv=1;if(e.type===1||e.type===4)mv=dist<4?-1:dist>6?1:0;if(e.boss&&dist<3)mv=0;if((e.type===0||e.type===2)&&dist<1.15)mv=0;const speed=e.speed*(e.slow>0?.65:1)*dt*mv;let dx=dir.x*speed,dz=dir.z*speed;
