function clearRoom(){clear=true;player.guard=false;mouseDown=false;touchAttack=false;earned+=1+Math.floor(player.fortune*3);for(const s of shots)disposeObject(s.mesh);shots.length=0;for(const t of traps){t.active=false;t.m.material.opacity=.15}const heal=12+player.clearHeal+(room%4===3?12:0);player.hp=Math.min(player.maxHp,player.hp+heal);player.ult=Math.min(100,player.ult+15);numberAt(hero.position,`+${heal}`,'heal');portal.material.opacity=.58;portalGlow.intensity=12;updateHud();if(room===11){endRun(true);return}announce('房间已净化','获得祝福 · 地牢中的星光回应了你');tone(620,.2,'sine',.07);state='reward-delay';clearDelay=.9;}
function showRewards(){const eligible=UPGRADES.filter(u=>(player.upgrades[u.id]||0)<u.max);const pool=[...eligible].sort(()=>rng()-.5).slice(0,3);showModal('reward',`<div class="modal-kicker">ROOM CLEARED · ${room+1} / 12</div><h2>收下一份微光</h2><p>选择一项祝福。本次冒险中持续生效，可叠加。</p><div class="choices">${pool.map((u,i)=>`<button class="choice" data-upgrade="${u.id}"><span>祝福 ${String(i+1).padStart(2,'0')} ${player.upgrades[u.id]?`· 已有 ${player.upgrades[u.id]} 层`:''}</span>${icon(u.icon)}<strong>${u.name}</strong><p>${u.desc}</p></button>`).join('')}</div><p class="small-note">已恢复生命 · 前往传送门继续探索</p>`);document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{const u=UPGRADES.find(v=>v.id===b.dataset.upgrade);u.apply(player);player.upgrades[u.id]=(player.upgrades[u.id]||0)+1;closeModal();state='playing';toast(`获得祝福 · ${u.name}`);updateHud()})}
function showRoutes(){if(room%4===2){nextRoom('normal');return}showModal('route',`<div class="modal-kicker">THE DUNGEON SHIFTS</div><h2>下一步，走向哪里？</h2><p>石墙悄然移动，前方出现了新的道路。</p><div class="choices"><button class="choice" data-route="normal"><span>稳步前进</span>${icon('leaf')}<strong>苔光小径</strong><p>常规战斗与祝福。<br>熟悉的微光引导着你。</p></button><button class="choice" data-route="elite"><span>高风险 · 高回报</span>${icon('sword')}<strong>勇者试炼</strong><p>更多、更强的敌人。<br>琥珀掉落增加 40%。</p></button><button class="choice" data-route="rest"><span>整装再出发</span>${icon('heart')}<strong>旅者营火</strong><p>花费 25 琥珀恢复 40 生命，再继续常规探索。</p><span class="price">${gold>=25?'25 琥珀':'琥珀不足 · 可免费继续'}</span></button></div>`);document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{const r=b.dataset.route;if(r==='rest'&&gold>=25){gold-=25;player.hp=Math.min(player.maxHp,player.hp+40)}nextRoom(r==='elite'?'elite':'normal')})}
function nextRoom(r){closeModal();room++;route=r;state='playing';enterRoom()}
function interact(){if(state!=='playing')return;const p=hero.position;if(Math.hypot(p.x-6.5,p.z+.7)<2&&!chestOpened){if(!clear){toast('清除敌人后，宝箱才会解锁');return}chestOpened=true;const amount=Math.round((18+biome*8)*(1+player.fortune));gold+=amount;earned+=2;mesh(chest,'ico',0xeed99b,0,1,0,.17,.22,.17,1);puff(6.5,-.7,0xe8d693,22);toast(`发现旧日珍藏 · +${amount} 琥珀 · +2 星屑`);tone(840,.3,'sine',.07);updateHud();return}if(p.z<-4.65&&Math.abs(p.x)<1.9){if(clear)showRoutes();else toast('击败所有敌人，打开传送门')}}
function showModal(mode,html){beforeModal=state;state=mode;keys.clear();mouseDown=false;touchAttack=false;guardTouch=false;joystick={x:0,y:0};$('joystick').firstElementChild.style.transform='';$('modalCard').innerHTML=html;$('modal').classList.remove('hidden');$('modalCard').querySelector('h2')?.setAttribute('id','modalTitle');requestAnimationFrame(()=>$('modalCard').querySelector('button:not(:disabled)')?.focus())}
function closeModal(){ $('modal').classList.add('hidden');mouseDown=false;touchAttack=false;keys.clear() }
function pause(){if(['playing','intro','reward-delay'].includes(state)){const previous=state;showModal('pause',`<div class="modal-kicker">TAKE A BREATH</div><h2>小骑士，歇一会儿。</h2><p>冒险会等你。${state==='intro'?'':`已到达第 ${room+1} 个房间，获得 ${earned} 星屑。`}</p><div class="run-stats"><div><strong>${kills}</strong>击败敌人</div><div><strong>${gold}</strong>琥珀</div><div><strong>${formatTime(elapsed)}</strong>冒险时间</div></div><button class="primary" id="resumeBtn">继续冒险</button><button class="secondary" id="restartBtn">重新开始</button>`);$('resumeBtn').onclick=()=>{closeModal();state=previous};$('restartBtn').onclick=()=>confirmRestart(previous)}else if(state==='pause'){closeModal();state=beforeModal}}
function confirmRestart(previous){showModal('confirm',`<div class="modal-kicker">A NEW BEGINNING</div><h2>重新踏上旅途？</h2><p>本局祝福与琥珀会重置。已获得的 ${earned} 星屑会保留到营地。</p><button class="primary" id="confirmRestart">保留星屑并重开</button><button class="secondary" id="cancelRestart">继续本局</button>`);$('confirmRestart').onclick=()=>{bankRun();startRun()};$('cancelRestart').onclick=()=>{closeModal();state=previous}}
function showHelp(){if(!['intro','playing','pause','reward-delay'].includes(state))return;const prev=state==='pause'?beforeModal:state;showModal('help',`<div class="modal-kicker">KNIGHT'S FIELD GUIDE</div><h2>慢慢来，也能走很远。</h2><p>清除房间敌人，选择祝福，再穿过发光传送门。<br>闯过三个区域与三位守卫，找回地下城的星光。</p><div class="help-grid"><div><kbd>W A S D / 方向键</kbd><b>移动</b>移动方向与画面一致。</div><div><kbd>鼠标 / J</kbd><b>瞄准与攻击</b>鼠标指向目标，按住左键攻击；J 自动瞄准。</div><div><kbd>SPACE</kbd><b>翻滚</b>短暂无敌，穿过弹幕。冷却 1.25 秒。</div><div><kbd>按住 SHIFT / K</kbd><b>缩壳</b>消耗体力，减免伤害并反伤。</div><div><kbd>1 2 3 4</kbd><b>切换武器</b>短剑、重锤、连弩、法杖随时切换。</div><div><kbd>Q</kbd><b>螺旋风暴</b>满能量时清除弹幕并震击周围敌人。</div><div><kbd>E</kbd><b>交互</b>开启宝箱，进入传送门。</div><div><kbd>ESC</kbd><b>暂停</b>每次阵亡保留星屑，可在营地永久成长。</div></div><p>触屏：左侧摇杆移动，右侧按住攻击自动瞄准。<br>橙色地面标记表示即将攻击；战斗中留意预警。</p><button class="primary" id="helpClose">准备好了</button>`);$('helpClose').onclick=()=>{closeModal();state=prev}}
function bankRun(){meta.shards+=earned;meta.best=Math.max(meta.best,room+1);meta.runs++;save();earned=0}
function endRun(won){const gained=earned+(won?20:0);earned=gained;bankRun();document.body.classList.remove('playing');showModal(won?'victory':'dead',`<div class="modal-kicker">${won?'THE LIGHT RETURNS':'EVERY SHELL HOLDS A STORY'}</div><h2>${won?'小小骑士，大大的胜利。':'这次，就走到这里。'}</h2><p>${won?'你穿越了整座地下城。三位守卫归于宁静，星光再次亮起。':'螺壳保护了最后一点微光。带着星屑回营地，让下一次走得更远。'}</p><div class="run-stats"><div><strong>${room+1}<small>/12</small></strong>探索房间</div><div><strong>${kills}</strong>击败敌人</div><div><strong>+${gained}</strong>保留星屑</div><div><strong>${formatTime(elapsed)}</strong>冒险时间</div></div><button class="primary" id="againBtn">再来一局</button><button class="secondary" id="endCampBtn">回到营地</button>`);$('againBtn').onclick=startRun;$('endCampBtn').onclick=()=>{closeModal();state='intro';biome=0;room=0;document.body.classList.add('at-camp');$('intro').classList.remove('hidden');resetPlayer();randomSeed(1608);generateRoom(true);showCamp()};tone(won?640:170,.65,'sine',.08)}
function showCamp(){if(state!=='intro'&&state!=='camp')return;const hpCost=15+meta.vitality*12,powerCost=20+meta.force*15;showModal('camp',`<div class="modal-kicker">THE QUIET CAMP</div><h2>让勇气，长进壳里。</h2><p>营地星屑：<b>${meta.shards}</b> · 最远抵达 ${meta.best} / 12 房<br>成长保存在当前浏览器。每次出发都会生效。</p><div class="choices camp-choices"><button class="choice" id="buyHp" ${meta.shards<hpCost?'disabled':''}>${icon('heart')}<strong>厚实螺壳 · ${meta.vitality} 级</strong><p>永久增加 10 点初始生命</p><span class="price">${hpCost} 星屑</span></button><button class="choice" id="buyPower" ${meta.shards<powerCost?'disabled':''}>${icon('sword')}<strong>骑士训练 · ${meta.force} 级</strong><p>永久增加 5% 初始伤害</p><span class="price">${powerCost} 星屑</span></button><div class="choice">${icon('gem')}<strong>旅途纪念</strong><p>完成冒险 ${meta.runs} 次<br>阵亡后星屑依然保留。<br>宝箱与首领掉落更多星屑。</p></div></div><button class="primary" id="campClose">返回营地</button>`);$('buyHp').onclick=()=>{if(meta.shards<hpCost)return;meta.shards-=hpCost;meta.vitality++;save();resetPlayer();updateHud();showCamp()};$('buyPower').onclick=()=>{if(meta.shards<powerCost)return;meta.shards-=powerCost;meta.force++;save();resetPlayer();showCamp()};$('campClose').onclick=()=>{closeModal();state='intro';updateHud()}}
function updateHud(){if(!player)return;$('healthFill').style.width=`${player.hp/player.maxHp*100}%`;$('healthText').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('gold').textContent=gold;$('shards').textContent=document.body.classList.contains('at-camp')?meta.shards:earned;$('campShards').textContent=`${meta.shards} 星屑`;$('timer').textContent=formatTime(elapsed);const b=BIOMES[biome];$('areaKicker').textContent=`${b.chapter} · ${b.en}`;$('areaName').textContent=b.name;$('roomLabel').textContent=document.body.classList.contains('at-camp')?'入口营地':`${b.names[room%4]} · ${room+1} / 12`;$('routeProgress').innerHTML=Array.from({length:12},(_,i)=>`<i class="${i<room?'done':i===room?'current':''}"></i>`).join('');$('blessings').innerHTML=Object.entries(player.upgrades).map(([id,n])=>`<span title="${UPGRADES.find(u=>u.id===id).desc}">${UPGRADES.find(u=>u.id===id).name}${n>1?` ×${n}`:''}</span>`).join('');$('objective').innerHTML=`<span class="objective-mark">◇</span><div><span>${clear?'房间已净化':room%4===3?'守卫之战':`第 ${wave} / ${waves} 波${route==='elite'?' · 精英试炼':''}`}</span><strong>${clear?'探索宝箱，前往发光传送门。':room%4===3?'击败守卫，寻找地下城的星光。':`清除 ${enemies.length} 个敌人，解锁前路。`}</strong></div>`}
function formatTime(t){return `${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`}
function updateMap(){const c=$('minimap').getContext('2d');c.clearRect(0,0,180,108);c.fillStyle='#3b504699';for(const tile of tiles){const[x,z]=tile.split(',').map(Number);c.fillRect(87+x*6,48+z*5,5,4)}c.fillStyle='#61735a';for(const o of obstacles)c.fillRect(85+o.x*6,46+o.z*5,5,5);c.fillStyle=clear?'#d7e7b2':'#677b64';c.fillRect(83,12,12,3);c.fillStyle='#dabb83';if(!chestOpened)c.fillRect(86+6.5*6,46-.7*5,5,5);c.fillStyle='#eab08b';for(const e of enemies){c.beginPath();c.arc(89+e.mesh.position.x*6,50+e.mesh.position.z*5,e.boss?3.5:2,0,TAU);c.fill()}c.fillStyle='#e2edbc';c.beginPath();c.arc(89+hero.position.x*6,50+hero.position.z*5,3,0,TAU);c.fill()}
function updatePlayer(dt){player.attack=Math.max(0,player.attack-dt);player.swing=Math.max(0,player.swing-dt);player.dash=Math.max(0,player.dash-dt);player.invuln=Math.max(0,player.invuln-dt);player.ult=Math.min(100,player.ult+dt*1.2);const guarding=keys.has('ShiftLeft')||keys.has('ShiftRight')||keys.has('KeyK')||guardTouch;player.guard=guarding&&player.stamina>2&&!clear;player.stamina=clamp(player.stamina+(player.guard?-27:20)*dt,0,100);
let x=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+joystick.x,z=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+joystick.y;const motion=new THREE.Vector3(x*.8+z*.6,0,z*.8-x*.6);if(motion.length()>1)motion.normalize();if(player.dashTime>0){player.dashTime-=dt;moveObj(hero,dashDir.x*dt*13,dashDir.z*dt*13,.4);heroBody.rotation.x-=dt*TAU*4}else{heroBody.rotation.x=0;const speed=4.4*player.speed*(player.guard?.38:1);moveObj(hero,motion.x*dt*speed,motion.z*dt*speed);}
if(pointerKnown&&!touchAttack&&!keys.has('KeyJ')){raycaster.setFromCamera(pointer,camera);raycaster.ray.intersectPlane(groundPlane,aimPoint);hero.rotation.y=Math.atan2(aimPoint.x-hero.position.x,aimPoint.z-hero.position.z)}else if(enemies.length&&(touchAttack||keys.has('KeyJ'))){const e=[...enemies].sort((a,b)=>a.mesh.position.distanceToSquared(hero.position)-b.mesh.position.distanceToSquared(hero.position))[0];hero.rotation.y=Math.atan2(e.mesh.position.x-hero.position.x,e.mesh.position.z-hero.position.z)}else if(motion.lengthSq()>.1)hero.rotation.y=Math.atan2(motion.x,motion.z);
heroBody.scale.set(1,player.guard?.64:1,player.guard?.85:1);heroBody.position.y=player.guard?.04:Math.sin(now*(motion.lengthSq()>.05?14:3))*.027;heroWeapon.rotation.z=player.swing>0?Math.sin(player.swing/.25*Math.PI)*-1.6:-.15;heroWeapon.rotation.x=selected===2?1.15:0;shield.rotation.y=player.guard?-.5:0;hero.visible=player.invuln>0&&player.dashTime<=0?Math.floor(now*16)%2===0:true;
if(mouseDown||keys.has('KeyJ')||touchAttack)attack();slimeTimer-=dt;if(motion.lengthSq()>.01&&slimeTimer<=0){slimeTimer=.17;const m=new THREE.Mesh(new THREE.CircleGeometry(.29,12),new THREE.MeshBasicMaterial({color:BIOMES[biome].glow,transparent:true,opacity:.13,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.set(hero.position.x,.012,hero.position.z);effects.add(m);fx.push({m,life:2.4,max:2.4,kind:'slime'})}
$('dashCooldown').style.height=`${player.dash/player.dashMax*61}%`;$('guardCooldown').style.height=`${(100-player.stamina)*.61}%`;$('ultCooldown').style.height=`${(100-player.ult)*.61}%`;$('ultimateBtn').style.opacity=player.ult>=100?'1':'.48';
const nearPortal=hero.position.z<-4.65&&Math.abs(hero.position.x)<1.9,nearChest=Math.hypot(hero.position.x-6.5,hero.position.z+.7)<2&&!chestOpened;$('interaction').classList.toggle('hidden',!nearPortal&&!nearChest);if(nearPortal)$('interaction').querySelector('span').textContent=clear?'穿过传送门':'消灭敌人以解锁';else if(nearChest)$('interaction').querySelector('span').textContent=clear?'打开宝箱':'宝箱尚未解锁'}
function updateEffects(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.vy-=dt*9;p.mesh.position.x+=p.vx*dt;p.mesh.position.y+=p.vy*dt;p.mesh.position.z+=p.vz*dt;p.mesh.scale.multiplyScalar(1-dt*.9);if(p.life<=0){disposeObject(p.mesh);particles.splice(i,1)}}for(let i=fx.length-1;i>=0;i--){const f=fx[i];f.life-=dt;const t=1-f.life/f.max;if(f.m.material)f.m.material.opacity=(1-t)*(f.kind==='slime'?.13:.7);if(f.kind==='ring')f.m.scale.setScalar(1+t*f.radius*5);if(f.life<=0){disposeObject(f.m);fx.splice(i,1)}}}
function loop(time){requestAnimationFrame(loop);let dt=Math.min((time-lastTime)/1000,.035);lastTime=time;now=time/1000;frame++;
if(state==='playing'){elapsed+=dt;updatePlayer(dt);if(!clear){updateEnemies(dt);updateShots(dt);for(const t of traps){t.t+=dt;const phase=t.t%4.8;t.active=phase>4.1;t.m.material.opacity=phase>3.2?.3+Math.sin(now*14)*.2:.08;t.m.material.color.set(t.active?0xf5d899:0xe8b587);if(t.active&&Math.hypot(hero.position.x-t.x,hero.position.z-t.z)<.9)hurtPlayer(12)}if(enemies.length===0){if(wave<waves){nextWaveTimer+=dt;if(nextWaveTimer>1.2){nextWaveTimer=0;spawnWave()}}else if(state==='playing')clearRoom()}}}
else if(state==='reward-delay'){clearDelay-=dt;if(clearDelay<=0)showRewards()}
if(['playing','intro','reward-delay'].includes(state)){updateEffects(dt);if(portal){portal.material.opacity=(clear?.46:.06)+(clear?Math.sin(now*2)*.12:0);portal.scale.x=1+Math.sin(now*1.4)*.035}world.children.forEach(c=>{if(c.userData.float)c.position.y=c.userData.float.base+Math.sin(now*.7+c.userData.float.phase)*.2});if(state==='intro'){heroBody.position.y=Math.sin(now*2)*.025;hero.rotation.y=.6+Math.sin(now*.3)*.15}}
const intro=document.body.classList.contains('at-camp');const target=new THREE.Vector3(intro?(width<700?-1.5:-4):hero.position.x*(width<700?1:.12),0,intro?2:hero.position.z*(width<700?1:.1));const camPos=target.clone().add(new THREE.Vector3(17,23,24));camera.position.lerp(camPos,.035);camera.lookAt(target);if(shake>0){camera.position.x+=(Math.random()-.5)*shake;camera.position.z+=(Math.random()-.5)*shake;shake=Math.max(0,shake-dt)}renderer.render(scene,camera);if(frame%9===0){updateHud();updateMap()}}
let guardTouch=false;
$('startBtn').onclick=startRun;$('campBtn').onclick=showCamp;$('pauseBtn').onclick=pause;$('helpBtn').onclick=showHelp;$('audioBtn').innerHTML=icon('mute');$('audioBtn').onclick=()=>{audioOn=!audioOn;$('audioBtn').innerHTML=icon(audioOn?'sound':'mute');$('audioBtn').title=audioOn?'关闭音效':'开启音效';$('audioBtn').setAttribute('aria-label',$('audioBtn').title);if(audioOn)tone(600,.12);toast(audioOn?'音效已开启':'音效已关闭')};
document.querySelectorAll('[data-weapon]').forEach(b=>b.onclick=()=>switchWeapon(+b.dataset.weapon));$('dashBtn').onclick=doDash;$('ultimateBtn').onclick=ultimate;$('guardBtn').addEventListener('pointerdown',e=>{guardTouch=true;e.currentTarget.setPointerCapture(e.pointerId)});$('guardBtn').addEventListener('pointerup',()=>guardTouch=false);$('guardBtn').addEventListener('pointercancel',()=>guardTouch=false);
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab'].includes(e.code)&&state==='playing')e.preventDefault();if(e.code==='Escape'){if(state==='help')$('helpClose')?.click();else if(state==='camp')$('campClose')?.click();else if(state==='confirm')$('cancelRestart')?.click();else pause();return}if(e.repeat)return;if(e.code==='Enter'&&state==='intro'){startRun();return}if(e.code==='Space')doDash();if(e.code==='KeyQ')ultimate();if(e.code==='KeyJ'){if(enemies.length){const nearest=[...enemies].sort((a,b)=>a.mesh.position.distanceToSquared(hero.position)-b.mesh.position.distanceToSquared(hero.position))[0];hero.rotation.y=Math.atan2(nearest.mesh.position.x-hero.position.x,nearest.mesh.position.z-hero.position.z)}attack();}if(e.code==='KeyE')interact();if(/^Digit[1-4]$/.test(e.code)&&['playing','intro'].includes(state))switchWeapon(+e.code.slice(-1)-1);keys.add(e.code)});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();mouseDown=false;touchAttack=false;guardTouch=false;if(state==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause()});
$('game').addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=$('game').getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);pointerKnown=true});$('game').addEventListener('pointerdown',e=>{if(e.button===0){mouseDown=true;$('game').setPointerCapture(e.pointerId)}});$('game').addEventListener('pointerup',()=>mouseDown=false);$('game').addEventListener('pointercancel',()=>mouseDown=false);$('game').addEventListener('contextmenu',e=>e.preventDefault());
const joy=$('joystick');let joyId=null;function setJoy(e){const r=joy.getBoundingClientRect();let x=(e.clientX-r.left-50)/35,y=(e.clientY-r.top-50)/35;const len=Math.hypot(x,y);if(len>1){x/=len;y/=len}joystick={x,y};joy.firstElementChild.style.transform=`translate(${x*30}px,${y*30}px)`}joy.onpointerdown=e=>{joyId=e.pointerId;joy.setPointerCapture(e.pointerId);setJoy(e)};joy.onpointermove=e=>{if(e.pointerId===joyId)setJoy(e)};joy.onpointerup=joy.onpointercancel=()=>{joyId=null;joystick={x:0,y:0};joy.firstElementChild.style.transform=''};$('touchAttack').onpointerdown=e=>{touchAttack=true;e.currentTarget.setPointerCapture(e.pointerId)};$('touchAttack').onpointerup=$('touchAttack').onpointercancel=()=>touchAttack=false;$('touchInteract').onclick=interact;
// Keep keyboard focus inside a modal; closing returns control to the game.
document.addEventListener('keydown',e=>{if(e.code!=='Tab'||$('modal').classList.contains('hidden'))return;const els=[...$('modalCard').querySelectorAll('button:not(:disabled)')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
function getGameState(){return{state,room:room+1,biome:BIOMES[biome].name,weapon:WEAPONS[selected].name,hp:Math.ceil(player.hp),maxHp:player.maxHp,enemies:enemies.length,gold,shards:earned,kills,elapsed:Math.floor(elapsed),seed,clear,upgrades:{...player.upgrades}}}
function setupWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;try{ctx.registerTool({name:'read_adventure_state',title:'查看冒险状态',description:'Read the current room, knight health, equipped weapon, and progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>getGameState()});ctx.registerTool({name:'equip_knight_weapon',title:'切换骑士武器',description:'Equip one of the four weapons in the same game and update the visible weapon bar.',inputSchema:{type:'object',properties:{weapon:{type:'integer',minimum:1,maximum:4}},required:['weapon'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!Number.isInteger(input?.weapon)||input.weapon<1||input.weapon>4)throw new Error('Weapon must be an integer from 1 to 4.');if(!['playing','intro'].includes(state))throw new Error('Close the current dialog before changing weapons.');switchWeapon(input.weapon-1);return getGameState()}})}catch(e){console.warn('WebMCP unavailable',e)}}
